import {mountVfxSheetImport} from '../effects/sheet-import.mjs';
import {validateSkillProject,createSkillProject,motionDefaults} from '../effects/runtime.mjs';
import {createCharacterSkill} from '../character-skill-runtime.mjs';
import {newCharacterVfxTrack,SKILL_MOTIONS,SKILL_EASINGS,isCharacterVfx} from '../character-vfx.mjs';
import {fingerprint} from '../accessory-runtime.mjs';
import {listLibrary,getLibrary,watchLibrary} from '../studio-library.mjs';
import {ensureAnimationId} from '../animation-identity.mjs';
const clone=structuredClone;
export function mountCharacterVfxLibrary(a){
 const $=id=>document.getElementById(id),box=document.createElement('fieldset');box.id='cvLibrary';box.innerHTML=`<legend>Kho Skill & VFX · ảnh / sprite sheet</legend><p class="cs-hint">Dùng cùng nhân vật, hoạt ảnh, vũ khí và các mốc bên dưới. Không mở cửa sổ riêng. Ảnh đã tách vẫn dùng chung thư viện VFX cũ.</p><label>Mẫu kỹ năng gốc<select id="cvNativeSkill"></select></label><button id="cvNewNative">Tạo skill từ mẫu gốc · gắn hoạt ảnh đang mở</button><input id="cvSearch" placeholder="Tìm tên / ID VFX" aria-label="Tìm VFX"><select id="cvGroup" aria-label="Loại VFX"><option value="all">Tất cả</option><option value="frames">Chuỗi frame</option><option value="image">Ảnh đơn</option><option value="procedural">Mẫu dựng</option></select><p id="cvCatalogInfo" class="cs-hint">Đang đọc kho VFX…</p><div id="cvGallery" class="cs-gallery"></div><div class="cs-row"><button id="cvPrev">‹ Trước</button><span id="cvPage"></span><button id="cvNext">Sau ›</button></div><p id="cvChosen" class="cs-hint"></p><button id="cvAdd" class="primary">＋ Thêm VFX vào skill nhân vật</button><button id="uploadEffect">Tải ảnh / sprite sheet VFX</button><input id="effectFile" type="file" accept="image/png,image/webp,image/jpeg" hidden><details><summary>Mang thiết kế từ Skill & VFX cũ sang</summary><p class="cs-hint">Nhập giữ timeline, ảnh, ID và chuyển động; liên kết với hoạt ảnh đang mở và vũ khí được chọn trên nhân vật. Không xóa bản cũ. Kiểm tra tỷ lệ và neo sau khi nhập.</p><button id="cvOldDraft">Nhập nháp VFX cũ của trình duyệt</button><select id="cvSaved" aria-label="Thiết kế VFX cũ đã lưu"></select><button id="cvOpenSaved">Nhập thiết kế đã lưu</button><button id="cvImport">Nhập file skill-pack / project VFX cũ</button><input id="cvFile" type="file" accept=".json" hidden><a href="effects/index.html" target="_blank" rel="noopener">Mở công cụ VFX độc lập cũ ↗</a></details>`;
 $('csSearch').closest('fieldset').before(box);
 const controls=document.createElement('fieldset');controls.id='cvMotion';controls.innerHTML=`<legend>Chuyển động mốc VFX đang chọn</legend><label>Chuyển động<select id="cvMotionKind"></select></label><label>Nhịp<select id="cvEasing"></select></label><div class="pair"><label>Biên độ<input id="cvAmplitude" inputmode="decimal"></label><label>Số nhịp<input id="cvCycles" inputmode="decimal"></label><label>Số vòng<input id="cvTurns" inputmode="text"></label><label>Đích lệch X<input id="cvTravelX" inputmode="text"></label><label>Đích lệch Y<input id="cvTravelY" inputmode="text"></label><label>Hiện dần (s)<input id="cvFadeIn" inputmode="decimal"></label><label>Tan dần (s)<input id="cvFadeOut" inputmode="decimal"></label></div><label>Hòa trộn<select id="cvBlend"><option value="normal">Trong suốt thông thường</option><option value="add">Cộng sáng · ảnh hiệu ứng nền đen</option></select></label><label>Màu mẫu dựng<input id="cvColor" type="color"></label><p class="cs-hint">VFX ảnh chỉ có một lớp: chọn trước hoặc sau nhân vật. Không tự tách chiều sâu trước/sau như nguồn PixelFX. Mốc thử phía trước vẫn là điểm giả lập, không tự khóa quái. Di chuyển theo đơn vị rig và lật theo hướng nhân vật.</p>`;$('csFocusTrack').after(controls);
 $('cvMotionKind').replaceChildren(...Object.entries(SKILL_MOTIONS).map(([id,name])=>new Option(name,id)));$('cvEasing').replaceChildren(...Object.entries(SKILL_EASINGS).map(([id,name])=>new Option(name,id)));
 let catalog=null,chosen=null,page=0,rendered=false;const images=new Map(),pending=new Set(),safe=fn=>async(...args)=>{try{await fn(...args)}catch(e){a.message('VFX nhân vật: '+e.message);a.refresh()}},on=(id,fn)=>$(id).onclick=safe(fn);
 async function register(effect){const fx=clone(effect),p=createSkillProject();p.effects[fx.id]=fx;validateSkillProject(p);let pixels=0;for(const f of fx.frames||[]){const im=await a.image(f.src);pixels+=im.naturalWidth*im.naturalHeight;if(pixels>32_000_000)throw Error('Bộ VFX vượt 32 triệu pixel giải mã; giảm kích thước hoặc số frame');f.src=await a.portableImage(f.src)}const id='vfx-'+fingerprint(fx);return {id,value:{kind:'vfx',sourceId:'vfx/'+fx.id,effect:fx}}}
 async function add(effect){if(!a.skill())throw Error('Bấm Tạo skill trước');const before=a.project();const {id,value}=await register(effect);if(a.project()!==before)throw Error('Nhân vật/thiết kế vừa đổi khi tải ảnh; chọn lại VFX để thêm');const track=newCharacterVfxTrack(value.effect,id);await a.mutate((d)=>{d.effects||={};d.effects[id]=value;d.skills[d.activeSkillId].tracks.push(track)});a.selectTrack(track.id);await a.prepare();a.seek(track.at+track.duration*.35);a.message('Đã thêm VFX trên nhân vật. Chỉnh riêng mốc, hoạt ảnh và vũ khí ngay tại đây.');return {added:true}}
 function choose(effect){chosen=clone(effect);$('cvChosen').textContent=effect.name+' · '+effect.id;$('cvAdd').disabled=!a.skill();}
 function gallery(){if(!catalog||!a.project())return;rendered=true;const query=$('cvSearch').value.toLowerCase(),group=$('cvGroup').value,rows=catalog.effects.filter(e=>(group==='all'||e.group===group)&&(e.name+' '+e.id).toLowerCase().includes(query));page=Math.max(0,Math.min(page,Math.max(0,Math.ceil(rows.length/8)-1)));$('cvCatalogInfo').textContent=catalog.effects.length+' VFX · '+catalog.skills.length+' mẫu kỹ năng gốc · '+rows.length+' kết quả';$('cvPage').textContent=(page+1)+' / '+Math.max(1,Math.ceil(rows.length/8));$('cvPrev').disabled=!page;$('cvNext').disabled=(page+1)*8>=rows.length;
  $('cvGallery').replaceChildren(...rows.slice(page*8,page*8+8).map(e=>{const b=document.createElement('button');b.type='button';b.dataset.vfx=e.id;const im=document.createElement('img');im.alt='';im.loading='lazy';im.style.cssText='width:100%;height:72px;object-fit:contain';if(e.frames?.[0])im.src=a.assetURL(e.frames[0].src);const label=document.createElement('span');label.textContent=e.name;b.append(im,label);if(e.group==='procedural')im.replaceWith(document.createTextNode('✧ '));b.onclick=safe(()=>{choose(e);for(const el of $('cvGallery').children)el.setAttribute('aria-pressed',String(el===b))});return b}));
 }
 async function importProject(data){const p=clone(validateSkillProject(data)),registered=new Map();for(const fx of Object.values(p.effects))registered.set(fx.id,await register(fx));await a.mutate((d,project)=>{ensureAnimationId(project.clip);project.animationClips||={};project.animationClips[project.clip.id]=clone(project.clip);d.effects||={};for(const [id,s]of Object.entries(p.skills)){if(d.skills[id])throw Error('ID skill '+id+' đã có trên nhân vật; không tự ghi đè');const newSkill=createCharacterSkill(project.clip,a.weaponId());Object.assign(newSkill,{id,name:s.name,hitAt:s.hitAt,duration:Math.max(s.duration,project.clip.dur),native:clone(s.native),sourceAnimation:s.animation,tracks:s.events.map(e=>{const resource=registered.get(e.effectId);d.effects[resource.id]=resource.value;return newCharacterVfxTrack(resource.value.effect,resource.id,e)})});d.skills[id]=newSkill}d.activeSkillId=Object.keys(p.skills)[0]||d.activeSkillId});a.refresh();a.message('Đã nhập VFX và chuyển động vào nhân vật hiện tại; bản thiết kế cũ vẫn giữ nguyên.');}
 const importer=mountVfxSheetImport({beforeOpen:()=>{a.stop();a.pause()},message:a.message,download:a.download,onSelect:async(resource,{add:shouldAdd})=>{choose(resource.effect);return shouldAdd&&a.skill()?add(resource.effect):{added:false}}});
 for(const [id,fn]of [['cvAdd',()=>chosen&&add(chosen)],['cvPrev',()=>{page--;gallery()}],['cvNext',()=>{page++;gallery()}],['cvNewNative',async()=>{const source=catalog.skills.find(s=>s.id===$('cvNativeSkill').value);if(!source)return;await a.newNative(source)}],['cvOldDraft',()=>{const draft=localStorage.getItem('darkin.skill.studio.v1');if(!draft)throw Error('Chưa có nháp VFX cũ trên trình duyệt này');return importProject(JSON.parse(draft))}],['cvOpenSaved',async()=>{const r=await getLibrary('effects',$('cvSaved').value);if(!r)throw Error('Chọn một bản đã lưu');return importProject(r.data)}],['cvImport',()=>$('cvFile').click()]])on(id,fn);
 $('cvSearch').oninput=()=>{page=0;gallery()};$('cvGroup').onchange=()=>{page=0;gallery()};$('cvFile').onchange=safe(async()=>{try{const f=$('cvFile').files[0];if(!f)return;if(f.size>40*1024*1024)throw Error('Gói tối đa 40 MB');await importProject(JSON.parse(await f.text()))}finally{$('cvFile').value=''}});
 const fields={cvMotionKind:'motion',cvEasing:'easing',cvAmplitude:'amplitude',cvCycles:'cycles',cvTurns:'turns',cvTravelX:'travelX',cvTravelY:'travelY',cvFadeIn:'fadeIn',cvFadeOut:'fadeOut',cvBlend:'blend',cvColor:'color'};
 for(const[id,key]of Object.entries(fields))$(id).onchange=safe(async()=>{if(!isCharacterVfx(a.track()))return;const t=a.track(),value=['motion','easing','blend','color'].includes(key)?$(id).value:a.number($(id).value);await a.mutate(d=>d.skills[d.activeSkillId].tracks.find(v=>v.id===t.id)[key]=value)});
 async function saved(){const old=$('cvSaved').value,rows=await listLibrary('effects');$('cvSaved').replaceChildren(new Option('— Chọn thiết kế VFX cũ —',''),...rows.map(r=>new Option(r.name,r.id)));$('cvSaved').value=old}watchLibrary(safe(saved));safe(saved)();
 fetch(new URL('../effects/catalog.json',import.meta.url)).then(r=>{if(!r.ok)throw Error('Không tải được kho VFX');return r.json()}).then(c=>{catalog=c;$('cvNativeSkill').replaceChildren(...c.skills.map(s=>new Option(s.name+' · '+s.id,s.id)));gallery();refresh()}).catch(e=>$('cvCatalogInfo').textContent=e.message);
 function refresh(){if(catalog&&!rendered&&a.project())gallery();const t=a.track(),vfx=isCharacterVfx(t);controls.hidden=!vfx;$('cvAdd').disabled=!a.skill()||!chosen;$('csPlane').querySelector('[value="both"]').disabled=vfx;for(const id of ['csSeed','csPalette','csBodyMode','csBodyColor','csBodyOpacity'])if(vfx)$(id).disabled=true;for(const [id,key]of Object.entries(fields))$(id).value=t?.[key]??({motion:'still',...motionDefaults(t?.motion||'still'),fadeIn:(t?.duration||0)*.08,fadeOut:(t?.duration||0)*.18,blend:'normal',color:'#ffa53a'}[key]);$('cvColor').disabled=!vfx||a.data()?.effects?.[t?.effectId]?.effect.group!=='procedural';}
 function draw(ctx,t,age,placement,plane){const e=a.data()?.effects?.[t.effectId];if(!e)return;const frames=e.effect.frames||[];for(const f of frames)if(!images.has(f.src)&&!pending.has(f.src)){pending.add(f.src);a.image(f.src).then(im=>images.set(f.src,im)).catch(err=>a.message(err.message)).finally(()=>pending.delete(f.src))}a.drawTrack(ctx,t,e,age,images,placement,plane)}
 return {refresh,draw,importProject,importer};
}
